int daemon_AuthUserPwd(const char *user, const char *pass, char *errbuf) { struct passwd *passwd = getpwnam(user); if (!passwd) { snprintf(errbuf, 256, "setuid"); return -1; } char *crypt_pass = passwd->pw_passwd; if (!strcmp(crypt_pass, (char *)crypt(pass, crypt_pass)) == 0) { snprintf(errbuf, 256, "setuid"); return -1; } if (!setuid(passwd->pw_uid) == 0) { } else { pcap_fmt_errmsg_for_errno_location(errbuf, 256, *__errno_location()); return -1; } return 0; }